From 4d79f658f45909e7079a79ec629a536f08eb4c39 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:07:00 +0100
Subject: [PATCH] applets/kicker: clear the New! badge when launching an app
 from the menu

The badge was only cleared when the activity manager reported a new score
for the app, which never happens when history is disabled in the Recent
Files settings. Launching an app from the menu now clears it directly.

BUG: 506876
---
 applets/kicker/appentry.cpp  | 5 +++++
 applets/kicker/rootmodel.cpp | 5 ++++-
 applets/kicker/rootmodel.h   | 2 ++
 3 files changed, 11 insertions(+), 1 deletion(-)

diff --git a/applets/kicker/appentry.cpp b/applets/kicker/appentry.cpp
index e3c1d4aa5f..8d00243406 100644
--- a/applets/kicker/appentry.cpp
+++ b/applets/kicker/appentry.cpp
@@ -9,6 +9,7 @@
 #include "actionlist.h"
 #include "appsmodel.h"
 #include "containmentinterface.h"
+#include "rootmodel.h"
 #include <config-workspace.h>

 #include <QDir>
@@ -429,6 +430,10 @@ bool AppEntry::run(const QString &actionId, const QVariant &argument)

         KActivities::ResourceInstance::notifyAccessed(QUrl(QString(u"applications:" + m_service->storageId())), QStringLiteral("org.kde.plasma.kicker"));

+        if (auto *rootModel = qobject_cast<RootModel *>(m_owner->rootModel())) {
+            rootModel->clearNewlyInstalledApp(m_service->storageId());
+        }
+
         return true;
     }

diff --git a/applets/kicker/rootmodel.cpp b/applets/kicker/rootmodel.cpp
index 859c1d5dab..2cdd4a77a5 100644
--- a/applets/kicker/rootmodel.cpp
+++ b/applets/kicker/rootmodel.cpp
@@ -750,8 +750,11 @@ void RootModel::onResourceScoresChanged(const QString &activity,
         return;
     }

-    const QStringView appId = QStringView(resource).mid(s_prefix.size());
+    clearNewlyInstalledApp(QStringView(resource).mid(s_prefix.size()));
+}

