diff --git a/applets/kicker/rootmodel.h b/applets/kicker/rootmodel.h
index 65e4500cd9..6eec57e82a 100644
--- a/applets/kicker/rootmodel.h
+++ b/applets/kicker/rootmodel.h
@@ -99,6 +99,8 @@ public:
     AbstractModel *favoritesModel() override;
